-- ==============================================================================
-- SEED DATA 3: KRITERIA GOLONGAN (PEDOMAN DUPRAS KAJ)
-- ==============================================================================

INSERT INTO public.kriteria_golongan (id, nama, badge_color, bg_light, border_light, text_color, icon_emoji, subjudul, garis_pengeluaran, tahap_metode, indikator, contoh_kondisi, rekomendasi_bantuan, is_default, urutan)
VALUES ('gol-sejahtera', 'Sejahtera', '#16a34a', '#f0fdf4', '#bbf7d0', '#15803d', '🟢', 'Keluarga Mandiri / Berdaya', 'Pengeluaran keluarga di atas Rp 8.500.000,- / bulan', 'Keluarga Mandiri (Kecukupan Ekonomi)', '• Gaji & Penghasilan: Penghasilan keluarga stabil dan berkecukupan (di atas Rp 8,5 juta per bulan).
• Kepemilikan Rumah: Memiliki rumah tinggal sendiri yang layak & permanen (atau mampu kontrak secara mandiri).
• Status Pekerjaan: Kepala keluarga atau anggota keluarga bekerja tetap (karyawan, PNS, profesional, atau wirausaha).
• Kebutuhan Hidup: Mampu mencukupi kebutuhan makan, sandang, papan, pendidikan anak, dan kesehatan sendiri.
• Kemandirian: Berdaya secara finansial dan tidak membutuhkan subsidi atau bantuan sosial gereja.', 'Karyawan tetap swasta/BUMN, pengusaha, profesional dengan penghasilan bulanan teratur dan stabil.', 'Tidak memerlukan subsidi ekonomi gereja. Diharapkan menjadi penopang gotong-royong, donatur iuran/kolekte lingkungan, serta penggerak solidaritas umat.', true, 1)
ON CONFLICT (id) DO UPDATE SET nama = EXCLUDED.nama, badge_color = EXCLUDED.badge_color, bg_light = EXCLUDED.bg_light, border_light = EXCLUDED.border_light, text_color = EXCLUDED.text_color, icon_emoji = EXCLUDED.icon_emoji, subjudul = EXCLUDED.subjudul, garis_pengeluaran = EXCLUDED.garis_pengeluaran, tahap_metode = EXCLUDED.tahap_metode, indikator = EXCLUDED.indikator, contoh_kondisi = EXCLUDED.contoh_kondisi, rekomendasi_bantuan = EXCLUDED.rekomendasi_bantuan, urutan = EXCLUDED.urutan;
INSERT INTO public.kriteria_golongan (id, nama, badge_color, bg_light, border_light, text_color, icon_emoji, subjudul, garis_pengeluaran, tahap_metode, indikator, contoh_kondisi, rekomendasi_bantuan, is_default, urutan)
VALUES ('gol-terduga-prasejahtera', 'Terduga Pra Sejahtera', '#eab308', '#fefce8', '#fef08a', '#a16207', '🟡', 'Perlu Ditinjau Pengurus Lingkungan', 'Pengeluaran keluarga di bawah Rp 8.500.000,- / bulan (Perlu Ditinjau)', 'Perlu Verifikasi & Kunjungan Kasih', '• Gaji & Penghasilan: Penghasilan keluarga di bawah Rp 8,5 juta per bulan dan masih belum stabil.
• Kepemilikan Rumah: Belum punya rumah sendiri (masih ngontrak, sewa murah, atau numpang keluarga), atau tinggal di permukiman padat.
• Status Pekerjaan: Belum ada pekerjaan tetap, pekerja kontrak, buruh harian lepas, ojek online, atau kerja serabutan.
• Kondisi Khusus: Memiliki tanggungan berat seperti anggota keluarga sakit kronis menahun, anak balita, lansia, atau difabel.
• Tindak Lanjut: Perlu dikunjungi oleh Pengurus Lingkungan untuk memastikan apakah membutuhkan bantuan sosial gereja.', 'Pekerja kontrak, buruh harian, keluarga yang mengontrak di gang sempit, atau keluarga dengan penghasilan tidak menentu.', 'Wajib dikunjungi oleh Pengurus Lingkungan (Ketua, Seksi Sosial/PSE, Sekretaris) untuk melihat langsung kondisi riil keluarga.', true, 2)
ON CONFLICT (id) DO UPDATE SET nama = EXCLUDED.nama, badge_color = EXCLUDED.badge_color, bg_light = EXCLUDED.bg_light, border_light = EXCLUDED.border_light, text_color = EXCLUDED.text_color, icon_emoji = EXCLUDED.icon_emoji, subjudul = EXCLUDED.subjudul, garis_pengeluaran = EXCLUDED.garis_pengeluaran, tahap_metode = EXCLUDED.tahap_metode, indikator = EXCLUDED.indikator, contoh_kondisi = EXCLUDED.contoh_kondisi, rekomendasi_bantuan = EXCLUDED.rekomendasi_bantuan, urutan = EXCLUDED.urutan;
INSERT INTO public.kriteria_golongan (id, nama, badge_color, bg_light, border_light, text_color, icon_emoji, subjudul, garis_pengeluaran, tahap_metode, indikator, contoh_kondisi, rekomendasi_bantuan, is_default, urutan)
VALUES ('gol-rentan-tidak-mampu', 'Rentan Tidak Mampu', '#ea580c', '#fff7ed', '#fed7aa', '#c2410c', '🟠', 'Penghasilan Pas-pasan / Rentan Kesulitan', 'Pengeluaran keluarga sekitar Rp 4.250.000 - Rp 8.500.000 / bulan', 'Prioritas Pemberdayaan & Beasiswa', '• Gaji & Penghasilan: Penghasilan pas-pasan (antara Rp 4,25 juta s/d Rp 8,5 juta per bulan), cukup untuk makan sehari-hari tapi sulit menabung.
• Kepemilikan Rumah: Mengontrak atau sewa rumah sederhana dengan biaya sewa yang memberatkan keuangan keluarga.
• Status Pekerjaan: Bekerja sebagai buruh lepas, pedagang kelontong kecil, pengemudi ojol, atau pekerja paruh waktu.
• Kerentanan Ekonomi: Gaji hanya cukup untuk sehari-hari, sangat rentan berutang jika ada sakit, PHK, atau musibah keluarga.
• Beban Tanggungan: Terbebani biaya pendidikan sekolah anak atau biaya perawatan lansia tanpa pensiun.', 'Buruh pabrik kontrak, pedagang kecil, pengemudi online, keluarga dengan beban biaya pendidikan anak yang berat.', 'Prioritas program pemberdayaan ekonomi umat (SABUK, Ayo Kerja, Credit Union), bantuan akses beasiswa pendidikan (ASAK / KIP), advokasi BPJS/KIS, serta subsidi sembako hari raya.', true, 3)
ON CONFLICT (id) DO UPDATE SET nama = EXCLUDED.nama, badge_color = EXCLUDED.badge_color, bg_light = EXCLUDED.bg_light, border_light = EXCLUDED.border_light, text_color = EXCLUDED.text_color, icon_emoji = EXCLUDED.icon_emoji, subjudul = EXCLUDED.subjudul, garis_pengeluaran = EXCLUDED.garis_pengeluaran, tahap_metode = EXCLUDED.tahap_metode, indikator = EXCLUDED.indikator, contoh_kondisi = EXCLUDED.contoh_kondisi, rekomendasi_bantuan = EXCLUDED.rekomendasi_bantuan, urutan = EXCLUDED.urutan;
INSERT INTO public.kriteria_golongan (id, nama, badge_color, bg_light, border_light, text_color, icon_emoji, subjudul, garis_pengeluaran, tahap_metode, indikator, contoh_kondisi, rekomendasi_bantuan, is_default, urutan)
VALUES ('gol-tidak-mampu', 'Tidak Mampu', '#dc2626', '#fef2f2', '#fecaca', '#b91c1c', '🔴', 'Sangat Membutuhkan Bantuan (Miskin)', 'Pengeluaran keluarga di bawah Rp 4.250.000,- / bulan', 'Bantuan Penuh & Prioritas Utama PSE', '• Gaji & Penghasilan: Sangat minim di bawah Rp 4,25 juta sekeluarga (sering kesulitan memenuhi makan harian).
• Kepemilikan Rumah: Tidak punya rumah tinggal sendiri, menumpang tanpa kepastian, atau kondisi hunian sangat memprihatinkan.
• Pencari Nafkah: Kepala keluarga menganggur, tidak mampu bekerja, lansia hidup sebatang kara, janda dhuafa, atau difabel berat.
• Kondisi Ekonomi: Tidak memiliki tabungan maupun barang berharga yang bisa dijual untuk bertahan hidup darurat.
• Kebutuhan Pokok: Sangat membutuhkan uluran tangan untuk makan harian, sewa tempat berteduh, dan biaya berobat.', 'Lansia sebatang kara tanpa penghasilan, keluarga dhuafa tanpa pencari nafkah, janda dengan anak kecil, penderita sakit berat terlantar.', 'Intervensi karitatif penuh dan prioritas utama PSE Paroki: santunan kebutuhan pokok sembako rutin bulanan, advokasi darurat medis, beasiswa penuh ASAK, bedah rumah, & bebas iuran kas.', true, 4)
ON CONFLICT (id) DO UPDATE SET nama = EXCLUDED.nama, badge_color = EXCLUDED.badge_color, bg_light = EXCLUDED.bg_light, border_light = EXCLUDED.border_light, text_color = EXCLUDED.text_color, icon_emoji = EXCLUDED.icon_emoji, subjudul = EXCLUDED.subjudul, garis_pengeluaran = EXCLUDED.garis_pengeluaran, tahap_metode = EXCLUDED.tahap_metode, indikator = EXCLUDED.indikator, contoh_kondisi = EXCLUDED.contoh_kondisi, rekomendasi_bantuan = EXCLUDED.rekomendasi_bantuan, urutan = EXCLUDED.urutan;

