VALUES ('kk-st-agnes-1-8', 'eea00d03-96b0-40a0-9465-5eb4e97496c6', 'Agnes Maruin', 'tytyan kencana, RT 005, RW 04, Marga Mulya, Bekasi Utara', '021-88879310', true)
